def vsub(a, b): return [x-y for x,y in zip(a,b)]

def random_distribution(n, rng):
    raw = [rng.random()+0.05 for _ in range(n)]
    s = sum(raw); return [x/s for x in raw]

rng = random.Random(7)
for trial in range(3):
    p = random_distribution(5, rng); q = random_distribution(5, rng)
    d = vsub(p, q)
    print(trial, chi_squared(p, q), fisher_form(q, d, d))

